func TestAgentsHierarchyOrderAndBoundary(t *testing.T) {
	root := t.TempDir()
	os.Mkdir(filepath.Join(root, ".git"), 0o755) // repo root: the walk stops here
	os.WriteFile(filepath.Join(root, "AGENTS.md"), []byte("ROOT RULES"), 0o644)
	sub := filepath.Join(root, "svc", "api")
	os.MkdirAll(sub, 0o755)
	os.WriteFile(filepath.Join(sub, "AGENTS.md"), []byte("API RULES"), 0o644)

	got, err := agentsHierarchy(sub)
	if err != nil {
		t.Fatalf("hierarchy: %v", err)
	}
	ri, ai := strings.Index(got, "ROOT RULES"), strings.Index(got, "API RULES")
	if ri < 0 || ai < 0 {
		t.Fatalf("both AGENTS.md should load:\n%s", got)
	}
	if ri > ai {
		t.Fatalf("outermost (ROOT) should come before nearest (API):\n%s", got)
	}
}

func TestAgentsHierarchyStopsAtGitRoot(t *testing.T) {
	root := t.TempDir()
	os.WriteFile(filepath.Join(root, "AGENTS.md"), []byte("ABOVE REPO"), 0o644)
	repo := filepath.Join(root, "repo")
	os.MkdirAll(filepath.Join(repo, ".git"), 0o755)
	os.WriteFile(filepath.Join(repo, "AGENTS.md"), []byte("REPO RULES"), 0o644)

	got, err := agentsHierarchy(repo)
	if err != nil {
		t.Fatalf("hierarchy: %v", err)
	}
	if !strings.Contains(got, "REPO RULES") {
		t.Fatal("repo AGENTS.md should load")
	}
	if strings.Contains(got, "ABOVE REPO") {
		t.Fatal("walk must not ascend above the git root")
	}
}

func TestAutoInstructionsToggle(t *testing.T) {
	cfg := Default()
	if !cfg.autoInstructionsEnabled() {
		t.Fatal("auto-instructions should default on")
