	off := false
	cfg.AutoInstructions = &off
	if cfg.autoInstructionsEnabled() {
		t.Fatal("auto-instructions should be off when set false")
	}
}

func TestDefaultCompactAt(t *testing.T) {
	if got := Default().CompactAt; got != 12000 {
		t.Fatalf("expected default compact_at 12000, got %d", got)
	}
}

func TestNoDefaultProviderErrors(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "config.json")
	os.WriteFile(path, []byte(`{"providers":{"litellm":{"type":"openai","base_url":"http://x/v1","model":"m"}},"shapes":{"s":{"loop":"oneshot","provider":"litellm","model":"m"}}}`), 0o644)
	t.Setenv("ERG_CONFIG", path)

	cfg, err := Load()
	if err != nil {
		t.Fatalf("load: %v", err)
	}
	// Bare run (no provider/shape) must error and list available providers,
	// rather than silently falling back to the built-in local provider.
	_, err = Resolve(cfg, Overrides{})
	if err == nil || !strings.Contains(err.Error(), "no default_provider") || !strings.Contains(err.Error(), "litellm") {
		t.Fatalf("expected no-default-provider error listing litellm, got %v", err)
	}
	// A shape that names a provider still resolves.
	if _, err := Resolve(cfg, Overrides{Shape: "s"}); err != nil {
		t.Fatalf("shape with a provider should resolve: %v", err)
	}
	// An explicit --provider still resolves.
	if _, err := Resolve(cfg, Overrides{Provider: "litellm"}); err != nil {
		t.Fatalf("explicit provider should resolve: %v", err)
	}
}

func TestComposeSystemFromFiles(t *testing.T) {
	dir := t.TempDir()
	instr := filepath.Join(dir, "AGENTS.md")
	os.WriteFile(instr, []byte("PROJECT RULE"), 0o644)
	shape := Shape{System: "APPEND", Instr: []string{instr}}
	got, err := composeSystem("BASE", shape, false)
	if err != nil {
		t.Fatalf("compose: %v", err)
	}
	for _, want := range []string{"BASE", "APPEND", "PROJECT RULE"} {
		if !strings.Contains(got, want) {
			t.Fatalf("missing %q in %q", want, got)
		}
	}
}

