func TestBufferEditing(t *testing.T) {
	var b buffer
	for _, r := range "helo" {
		b.insert(r)
	}
	if b.string() != "helo" {
		t.Fatalf("got %q", b.string())
	}
	// Insert 'l' to fix "helo" -> "hello": move cursor before the last 'o'.
	b.left()
	b.insert('l')
	if b.string() != "hello" {
		t.Fatalf("insert-at-cursor got %q", b.string())
	}
	b.home()
	b.deleteFwd() // remove 'h'
	if b.string() != "ello" {
		t.Fatalf("deleteFwd got %q", b.string())
	}
	b.end()
	b.backspace() // remove trailing 'o'
	if b.string() != "ell" {
		t.Fatalf("backspace got %q", b.string())
	}
}

func TestBufferKills(t *testing.T) {
	var b buffer
	b.set("one two three")
	b.killWord() // cursor at end -> removes "three"
	if b.string() != "one two " {
		t.Fatalf("killWord got %q", b.string())
	}
	b.killLine()
	if b.string() != "" || b.pos != 0 {
		t.Fatalf("killLine got %q pos %d", b.string(), b.pos)
	}
	b.set("keep|cut")
	// place cursor after "keep" (index 4) and kill to end
	b.home()
	for i := 0; i < 4; i++ {
		b.right()
	}
	b.killToEnd()
	if b.string() != "keep" {
		t.Fatalf("killToEnd got %q", b.string())
	}
}

func decodeAll(t *testing.T, s string) []keyEvent {
	t.Helper()
	br := bufio.NewReader(strings.NewReader(s))
	var out []keyEvent
	for {
		k, err := decode(br)
		if err != nil {
			break
		}
		out = append(out, k)
	}
	return out
}

func TestDecodeKeys(t *testing.T) {
	cases := map[string]keyKind{
		"a":       keyRune,
		"\r":      keyEnter,
		"\n":      keyEnter,
		"\x7f":    keyBackspace,
		"\x03":    keyInterrupt,
		"\x04":    keyEOF,
		"\x01":    keyHome,
		"\x05":    keyEnd,
		"\x1b[A":  keyUp,
		"\x1b[B":  keyDown,
		"\x1b[C":  keyRight,
		"\x1b[D":  keyLeft,
		"\x1b[H":  keyHome,
		"\x1b[3~": keyDelete,
		"\x1bOA":  keyUp, // application cursor mode
	}
	for input, want := range cases {
		got := decodeAll(t, input)
		if len(got) == 0 || got[0].kind != want {
			t.Fatalf("decode %q: got %+v, want kind %d", input, got, want)
		}
	}
	if got := decodeAll(t, "x"); got[0].r != 'x' {
		t.Fatalf("rune decode got %q", got[0].r)
	}
}

func TestHistoryNavigation(t *testing.T) {
	e := &Editor{hist: []string{"first", "second", "third"}}
	var b buffer
	b.set("draft")
	cursor := len(e.hist)
	stash := ""

	e.histPrev(&b, &cursor, &stash) // -> third
	if b.string() != "third" {
		t.Fatalf("up1 got %q", b.string())
	}
	e.histPrev(&b, &cursor, &stash) // -> second
	e.histPrev(&b, &cursor, &stash) // -> first
	if b.string() != "first" {
		t.Fatalf("up3 got %q", b.string())
	}
	e.histPrev(&b, &cursor, &stash) // clamp at oldest
	if b.string() != "first" {
		t.Fatalf("clamp got %q", b.string())
	}
	e.histNext(&b, &cursor, &stash) // -> second
	e.histNext(&b, &cursor, &stash) // -> third
	e.histNext(&b, &cursor, &stash) // -> back to the stashed draft
	if b.string() != "draft" {
		t.Fatalf("restore stash got %q", b.string())
	}
}

func TestHistoryPersistence(t *testing.T) {
	path := filepath.Join(t.TempDir(), "sub", "coder.history")
	e := &Editor{path: path}
	e.add("build")
	e.add("build") // consecutive dup -> skipped
	e.add("  ")    // blank -> skipped
	e.add("test")

	got := loadHistory(path)
	if strings.Join(got, ",") != "build,test" {
		t.Fatalf("persisted history = %v", got)
	}
}
